func run() -> float:
	var jump_height: float = 100.0
	var jump_time_to_peak: float = 0.5
	var gravity: float = (2.0 * jump_height) / (jump_time_to_peak * jump_time_to_peak)
	return gravity

func run() -> float:
	var velocity_y: float = -600.0
	var is_released: bool = true
	if is_released and velocity_y < 0.0:
		velocity_y *= 0.5
	return velocity_y

